cumsum_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void cumsum_kernel(const scalar_t* __restrict__ input,
                              scalar_t* __restrict__ output,
                              int rows,
                              int cols) {
    // one block per row
    int row = blockIdx.x;
    if (row >= rows) return;

    extern __shared__ float shared[];          // size = 2 * blockDim.x
    float* chunk_sum   = shared;               // [blockDim.x]
    float* chunk_off   = shared + blockDim.x;  // [blockDim.x]

    int tid = threadIdx.x;
    int num_threads = blockDim.x;

    // ---- Phase 1: compute sum of each chunk ----
    int chunk_len = (cols + num_threads - 1) / num_threads; // ceil
    int start = tid * chunk_len;
    int end   = min(start + chunk_len, cols);

    float sum = 0.0f;
    for (int i = start; i < end; ++i) {
        // load half and convert to float for accumulation
        sum += __half2float(input[row * cols + i]);
    }
    chunk_sum[tid] = sum;
    __syncthreads();

    // ---- Phase 2: exclusive scan of chunk sums (single thread) ----
    if (tid == 0) {
        float acc = 0.0f;
        for (int i = 0; i < num_threads; ++i) {
            float cur = chunk_sum[i];
            chunk_off[i] = acc;
            acc += cur;
        }
    }
    __syncthreads();

    // ---- Phase 3: write final prefix sums ----
    float prefix = chunk_off[tid];
    for (int i = start; i < end; ++i) {
        prefix += __half2float(input[row * cols + i]);
        output[row * cols + i] = __float2half(prefix);
    }
}

// dispatch
void launch_cumsum(const at::Half* input,
                   at::Half* output,
                   int rows,
                   int cols,
                   cudaStream_t stream) {
    const int threads = 256;
    const dim3 blocks(rows);
    const size_t shared_mem = 2 * threads * sizeof(float);
    cumsum_kernel<<<blocks, threads, shared_mem, stream>>>(
        input, output, rows, cols);
}
'''

# Compile the CUDA kernel
cumsum_module = load_inline(name='cumsum_cuda',
                            cpp_sources='',
                            cuda_sources=cumsum_src,
                            functions=['launch_cumsum'],
                            verbose=False)

class CumsumFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input, dim):
        if not input.is_cuda:
            raise RuntimeError("CumsumFunction only supports CUDA tensors")
        if input.dtype != torch.float16:
            raise RuntimeError("CumsumFunction only supports float16 tensors")
        if dim != 1:
            raise NotImplementedError("Only dim=1 is supported in this custom kernel")
        if input.dim() != 2:
            raise NotImplementedError("Only 2‑D tensors are supported in this custom kernel")

        rows, cols = input.shape
        output = torch.empty_like(input)

        # launch kernel
        stream = torch.cuda.current_stream().cuda_stream
        cumsum_module.launch_cumsum(input.data_ptr(),
                                    output.data_ptr(),
                                    rows,
                                    cols,
                                    stream)

        return output

    @staticmethod
    def backward(ctx, grad_output):
        # The gradient of cumsum is a reverse cumulative sum.
        # For simplicity we fall back to PyTorch implementation.
        return torch.cumsum(grad_output, dim=1), None


class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model that uses a custom CUDA kernel
    to compute the cumulative sum along the given dimension.
    """
    def __init__(self, dim):
        super().__init__()
        self.dim = dim

    def forward(self, x):
        return CumsumFunction.apply(x, self.dim)


